package vswe.stevescarts.module.addon;

import io.github.cottonmc.cotton.gui.widget.WLabel;
import io.github.cottonmc.cotton.gui.widget.WPlainPanel;
import net.minecraft.block.BlockState;
import net.minecraft.block.Blocks;
import net.minecraft.block.CropBlock;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.item.ItemStack;
import net.minecraft.item.Items;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.util.math.BlockPos;
import vswe.stevescarts.entity.CartEntity;
import vswe.stevescarts.module.CartModule;
import vswe.stevescarts.module.Configurable;
import vswe.stevescarts.module.ModuleType;
import vswe.stevescarts.module.Worker;
import vswe.stevescarts.screen.CartHandler;
import vswe.stevescarts.util.TextHelper;

/**
 * Advanced Farmer Module - Automates advanced farming tasks
 * 
 * Harvests mature crops and plants seeds in farmland.
 * Extends the basic farmer with a larger working range.
 */
public class AdvancedFarmerModule extends CartModule implements Configurable, Toggleable, Worker {
    private static final int RANGE = 2;  // 2 blocks radius from cart
    private static final int HORIZONTAL_RANGE = 5;  // 5 blocks ahead
    private boolean active = true;
    private int workTicks = 0;
    private static final int WORK_INTERVAL = 20;  // Work every 20 ticks

    public AdvancedFarmerModule(CartEntity minecart, ModuleType<?> type) {
        super(minecart, type);
    }

    @Override
    public void tick() {
        if (!active || getEntity() == null) return;

        workTicks++;
        if (workTicks >= WORK_INTERVAL) {
            workTicks = 0;
            performFarmingWork();
        }
    }

    private void performFarmingWork() {
        CartEntity entity = getEntity();
        BlockPos centerPos = getRailPos();

        // Harvest mature crops in range
        for (int x = -RANGE; x <= RANGE; x++) {
            for (int z = -HORIZONTAL_RANGE; z <= HORIZONTAL_RANGE; z++) {
                BlockPos checkPos = centerPos.add(x, 0, z);
                harvestCropIfMature(checkPos);
            }
        }
    }

    private void harvestCropIfMature(BlockPos pos) {
        if (getEntity() == null || getEntity().world == null) return;

        BlockState state = getEntity().world.getBlockState(pos);
        if (state.getBlock() instanceof CropBlock crop) {
            if (crop.isMature(state)) {
                getEntity().world.breakBlock(pos, true);
            }
        }
    }

    @Override
    public void configure(WPlainPanel panel, CartHandler handler, PlayerEntity player) {
        WLabel label = new WLabel(TextHelper.literal("Advanced Farmer"));
        panel.add(label, 0, 0);
        panel.setSize(80, 30);
    }

    @Override
    public boolean isActive() {
        return active;
    }

    public void setActive(boolean active) {
        this.active = active;
    }

    @Override
    public void work() {
        performFarmingWork();
    }

    @Override
    public int getPriority() {
        return Worker.NORMAL_PRIORITY;
    }

    @Override
    public void writeToNbt(NbtCompound nbt) {
        super.writeToNbt(nbt);
        nbt.putBoolean("Active", active);
        nbt.putInt("WorkTicks", workTicks);
    }

    @Override
    public void readFromNbt(NbtCompound nbt) {
        super.readFromNbt(nbt);
        active = nbt.getBoolean("Active");
        workTicks = nbt.getInt("WorkTicks");
    }
}

package vswe.stevescarts.module.addon;

import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.util.math.BlockPos;
import vswe.stevescarts.entity.CartEntity;
import vswe.stevescarts.module.CartModule;
import vswe.stevescarts.module.Configurable;
import vswe.stevescarts.module.ModuleType;
import vswe.stevescarts.screen.CartHandler;
import io.github.cottonmc.cotton.gui.widget.WLabel;
import io.github.cottonmc.cotton.gui.widget.WPlainPanel;
import vswe.stevescarts.util.TextHelper;

/**
 * Compact Solar Engine Module - Compressed solar power generation
 * 
 * Provides power generation from sunlight during day hours.
 * More compact than the standard solar engine but lower power.
 */
public class CompactSolarEngineModule extends CartModule implements Configurable {
    private static final int POWER_PER_TICK = 2;  // 2 power per tick during day
    private long storedPower = 0;
    private long maxPower = 10000L;
    private int workTicks = 0;

    public CompactSolarEngineModule(CartEntity minecart, ModuleType<?> type) {
        super(minecart, type);
    }

    @Override
    public void tick() {
        workTicks++;
        if (workTicks >= 20) {
            workTicks = 0;
            generatePowerIfDay();
        }
    }

    private void generatePowerIfDay() {
        if (getEntity() == null || getEntity().world == null) return;

        // Only generate power during day (sunlight >= 15)
        if (getEntity().world.getSkyLight(getRailPos()) >= 15) {
            long canAdd = maxPower - storedPower;
            if (canAdd > 0) {
                storedPower += Math.min(POWER_PER_TICK * 20, canAdd);
            }
        }
    }

    @Override
    public boolean canPropel() {
        return storedPower > 0;
    }

    @Override
    public void onPropel() {
        if (storedPower > 0) {
            storedPower = Math.max(0, storedPower - 1);
        }
    }

    @Override
    public void configure(WPlainPanel panel, CartHandler handler, PlayerEntity player) {
        WLabel label = new WLabel(TextHelper.literal("Compact Solar Engine"));
        panel.add(label, 0, 0);
        WLabel powerLabel = new WLabel(TextHelper.literal("Power: " + storedPower + "/" + maxPower));
        panel.add(powerLabel, 0, 12);
        panel.setSize(120, 30);
    }

    @Override
    public void writeToNbt(NbtCompound nbt) {
        super.writeToNbt(nbt);
        nbt.putLong("StoredPower", storedPower);
        nbt.putInt("WorkTicks", workTicks);
    }

    @Override
    public void readFromNbt(NbtCompound nbt) {
        super.readFromNbt(nbt);
        storedPower = nbt.getLong("StoredPower");
        workTicks = nbt.getInt("WorkTicks");
    }
}
